
  IF OBJECT_ID ('DIM_Dates', 'U')  IS   NULL 
  begin

create table DIM_Dates (
[Date Key] date not null,
[Date Number] int not null,
[Full Date] smalldatetime,
[Full Date US] varchar(100),
[Day Of Week] tinyint,
[Day Num In Month] tinyint,
[Day Num Overall] smallint,
[Day Name] varchar(13),
[Day Abbrev] char(3),
[Week Num In Year] tinyint,
[Week Num Overall] smallint,
[Month] tinyint,
[Month Num Overall] smallint,
[Month Name] varchar(13),
[Month Abbrev] char(3),
[Quarter] tinyint,
[Year] smallint,
[Yearmo] int,
[Month End Flag] varchar(100),
primary key ([Date Key]));







end